    public static class SteamPickerQa {
        static void Need(bool value,string text){if(!value)throw new Exception(text);}
        static string Esc(string value){return value.Replace("\\","\\\\").Replace("\"","\\\"");}
        static string Acf(string id,string name,string folder,string state){return "\"AppState\" { \"appid\" \""+id+"\" \"name\" \""+Esc(name)+"\" \"installdir\" \""+Esc(folder)+"\" \"StateFlags\" \""+state+"\" }";}
        public static void Core(string directory){Directory.CreateDirectory(directory);var results=new List<string>();try{string root=Path.Combine(directory,"steam-library-fixture-"+Guid.NewGuid().ToString("N")),first=Path.Combine(root,"Steam"),second=Path.Combine(root,"OtherLibrary"),apps=Path.Combine(first,"steamapps"),apps2=Path.Combine(second,"steamapps");Directory.CreateDirectory(apps);Directory.CreateDirectory(apps2);Directory.CreateDirectory(Path.Combine(apps,"common","Portal"));Directory.CreateDirectory(Path.Combine(apps2,"common","Stardew"));Directory.CreateDirectory(Path.Combine(apps2,"common","Incomplete"));File.WriteAllText(Path.Combine(apps,"libraryfolders.vdf"),"\"libraryfolders\" { \"0\" { \"path\" \""+Esc(first)+"\" } \"1\" { \"path\" \""+Esc(second)+"\" } }");File.WriteAllText(Path.Combine(apps,"appmanifest_620.acf"),Acf("620","Portal \"Zwei\"","Portal","4"));File.WriteAllText(Path.Combine(apps2,"appmanifest_413150.acf"),Acf("413150","Stardew Valley","Stardew","68"));File.WriteAllText(Path.Combine(apps2,"appmanifest_999.acf"),Acf("999","Incomplete","Incomplete","1026"));File.WriteAllText(Path.Combine(apps2,"appmanifest_888.acf"),Acf("888","Missing","Missing","4"));File.WriteAllText(Path.Combine(apps2,"appmanifest_620.acf"),Acf("620","Duplicate","Stardew","4"));File.WriteAllText(Path.Combine(apps,"appmanifest_666.acf"),"\"AppState\" { broken");
            var snapshot=SteamLibrary.Read(new[]{first},CancellationToken.None,false);Need(snapshot.Games.Length==2&&snapshot.Games.Any(g=>g.Id=="620"&&g.Name=="Portal \"Zwei\"")&&snapshot.Games.Any(g=>g.Id=="413150"),"Modern libraries, escaped title, installed/running flags, duplicate or broken filtering");Need(SteamLibrary.Manifest(Acf("1","Escape",@"..\..\outside","4"),Path.Combine(apps,"appmanifest_1.acf"))==null,"Folder traversal accepted");Need(SteamLibrary.Manifest(Acf("2","Mismatch","Portal","4"),Path.Combine(apps,"appmanifest_3.acf"))==null,"Mismatched app identity accepted");File.WriteAllText(Path.Combine(apps,"libraryfolders.vdf"),"// old format\n\"LibraryFolders\" { \"1\" \""+Esc(second)+"\" }");Need(SteamLibrary.Read(new[]{first},CancellationToken.None,false).Games.Length==2,"Old library format lost");bool cancelled=false;using(var cancel=new CancellationTokenSource()){cancel.Cancel();try{SteamLibrary.Read(new[]{first},cancel.Token,false);}catch(OperationCanceledException){cancelled=true;}}Need(cancelled,"Cancellation ignored");results.Add("PASS: Real temporary files cover multiple modern/legacy Steam libraries, escaped names, installed/running states, duplicates, incomplete/missing/broken apps, traversal/identity rejection and cancellation. Nothing launched; no personal Steam or Iris configuration changed.");results.Add("ALL STEAM LIBRARY CORE CHECKS PASSED");}catch(Exception ex){Environment.ExitCode=1;results.Add("FAILED: "+ex);}File.WriteAllLines(Path.Combine(directory,"steam-library-core-test.txt"),results);}
        public static void Probe(string directory){Directory.CreateDirectory(directory);var results=new List<string>();try{using(var timeout=new CancellationTokenSource(10000)){var data=SteamLibrary.Read(timeout.Token);results.Add("Read-only LIVE installed Steam catalog; no game launched or personal settings changed.");results.Add("Installed games: "+data.Games.Length+"; original local icons: "+data.Games.Count(g=>g.Icon!=null));foreach(var game in data.Games)results.Add(game.Name+" | "+game.Id);results.Add(data.Message);}}catch(Exception ex){results.Add("Probe incomplete: "+ex.Message);Environment.ExitCode=1;}File.WriteAllLines(Path.Combine(directory,"steam-library-live.txt"),results);}
    }
