on.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));uiMotion.SnapAll();Dispatcher.Invoke(DispatcherPriority.ContextIdle,new Action(delegate{}));var host=(AddonRecordingHost)addonTestHost;if(host.Calls.Count!=0||addonDeck.At(0).Action.Target!="620"||AddonCatalog.Load(AddonPath).At(0).Action.Title!="Portal 2")throw new Exception("Selection/save executes action or fails persistence");SwitchPage("Add-ons",false);CloseNotch(true);Open();SetQuickBar(true);RefreshAddonTiles();uiMotion.SnapAll();UpdateLayout();Capture("preview-steam-game-tile.png");RunAddon(0);WaitAddonUi();if(host.Calls.Count!=1||host.Calls[0]!="launch:steam://rungameid/620|")throw new Exception("Selected game route changed");
            var custom=package.Actions.First(a=>a.Kind=="steam").Copy();custom.Target="730";custom.Title="Mein Feierabend";custom.Icon="\uE734";OpenAddonWindow("Steam-Spiel bearbeiten");EditAddonAction(1,package,custom);uiMotion.SnapAll();if(addonTargetBox.Text!="730"||addonNameBox.Text!="Mein Feierabend")throw new Exception("Existing unknown ID/custom title lost");addonSaveButton.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));uiMotion.SnapAll();Dispatcher.Invoke(DispatcherPriority.ContextIdle,new Action(delegate{}));if(addonDeck.At(1).Action.Target!="730"||addonDeck.At(1).Action.Icon!="\uE734")throw new Exception("Legacy binding/icon lost");OpenAddonWindow("Steam-Liste");ShowSteamGamePicker(0,package,package.Actions.First(a=>a.Kind=="steam").Copy());ShowAddonDialogPage("qa-other",AddonPanel(),1);Dispatcher.Invoke(DispatcherPriority.ContextIdle,new Action(delegate{}));if(addonDialogPage!="qa-other")throw new Exception("Late Steam reply replaces newer page");CloseAddonWindow();results.Add("PASS: Native searchable game list opens directly; selection applies name and hidden internal ID, original-icon drawing and editor animation; selecting/saving launches nothing; only explicit tile click reaches recording host. Custom titles/icons and old unlisted bindings persist; stale dialog answers are discarded. Images/games in screenshots are fixtures.");results.Add("ALL STEAM PICKER UI CHECKS PASSED");}catch(Exception ex){Environment.ExitCode=1;results.Add("FAILED: "+ex);}finally{if(addonWindow!=null)CloseAddonWindow();File.WriteAllLines(Path.Combine(root,"steam-picker-ui-test.txt"),results);Close();}}
